SELECT ProfileEvents['WriteBufferFromFileDescriptorWriteBytes'] AS written_bytes, rows, duration_ms
FROM system.part_log WHERE database = 'upsert_lab' AND table = 'ru_1' AND event_type = 'NewPart'
ORDER BY event_time_microseconds DESC LIMIT 1;

SELECT ProfileEvents['WriteBufferFromFileDescriptorWriteBytes'] AS written_bytes, rows, duration_ms
FROM system.part_log WHERE database = 'upsert_lab' AND table = 'ru_1p' AND event_type = 'NewPart'
ORDER BY event_time_microseconds DESC LIMIT 1;

SELECT ProfileEvents['WriteBufferFromFileDescriptorWriteBytes'] AS written_bytes, rows, duration_ms
FROM system.part_log WHERE database = 'upsert_lab' AND table = 'ru_10p' AND event_type = 'NewPart'
ORDER BY event_time_microseconds DESC LIMIT 1;

SELECT sumIf(ProfileEvents['WriteBufferFromFileDescriptorWriteBytes'], event_type = 'NewPart' AND startsWith(part_name, 'patch-')) AS patch_written_bytes,
       sumIf(ProfileEvents['WriteBufferFromFileDescriptorWriteBytes'], event_type = 'MutatePart') AS mutate_written_bytes
FROM system.part_log WHERE database = 'upsert_lab' AND table = 'del_patch';

SELECT ProfileEvents['WriteBufferFromFileDescriptorWriteBytes'] AS written_bytes, rows
FROM system.part_log WHERE database = 'upsert_lab' AND table = 's_ru_1p' AND event_type = 'NewPart'
ORDER BY event_time_microseconds DESC LIMIT 1;

SELECT ProfileEvents['WriteBufferFromFileDescriptorWriteBytes'] AS written_bytes, rows
FROM system.part_log WHERE database = 'upsert_lab' AND table = 's_ru_10p' AND event_type = 'NewPart'
ORDER BY event_time_microseconds DESC LIMIT 1;
